import React, { useState, useEffect } from 'react';
import PlayerRow from './PlayerRow';
import ChampionsLeagueFooter from './ChampionsLeagueFooter';
import ChampionsLeagueHeader from './ChampionsLeagueHeader';

const ChampionsLeagueScorers = () => {
  const [players, setPlayers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeModal, setActiveModal] = useState(null);
  const [modalData, setModalData] = useState(null);
  const [selectedSection, setSelectedSection] = useState(null);
  const [selectedPlayer, setSelectedPlayer] = useState(null);

  // Cargar datos del archivo JSON
  useEffect(() => {
    setIsLoading(true);

    fetch('/data/top-champions-league-scorers.json')
      .then(response => {
        if (!response.ok) {
          throw new Error('Error al cargar los datos de los goleadores');
        }
        return response.json();
      })
      .then(data => {
        // Transformar los datos al formato que necesitamos
        const formattedPlayers = data.map((player, index) => ({
          position: index + 1,
          name: player.nombre,
          team: player.equipos.map(t => t.equipo).join('/'),
          goals: player.goles_totales,
          fullData: player // Guardamos todos los datos para usar en los modales
        }));
        setPlayers(formattedPlayers);
        setIsLoading(false);
      })
      .catch(err => {
        console.error('Error fetching data:', err);
        setError(err.message);
        setIsLoading(false);
      });
  }, []);

  // Funciones para mostrar información detallada
  const showPlayerInfo = (player) => {
    if (!player || !player.fullData) {
      console.error('Datos de jugador incompletos:', player);
      return;
    }

    setSelectedPlayer(player);
    setActiveModal('playerInfo');
  };

  const handleSectionChange = (section) => {
    setSelectedSection(section);
    setActiveModal(null);
  };

  const closeModal = () => {
    setActiveModal(null);
    setModalData(null);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center">
          <div className="w-32 h-32 mx-auto mb-6 rounded-xl shadow-lg p-2 border border-champions-gold/30 bg-champions-blue/80">
            <img 
              src="/images/logos/cc.png" 
              alt="Champions League Logo" 
              className="w-full h-full object-contain animate-pulse"
            />
          </div>
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-champions-gold mx-auto"></div>
          <p className="mt-4 text-lg text-white">
            <span className="champions-star">★</span> Cargando goleadores <span className="champions-star">★</span>
          </p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center text-red-500">
          <p className="text-2xl font-bold text-white">Error al cargar los datos</p>
          <p className="mt-2 text-champions-gold">{error}</p>
        </div>
      </div>
    );
  }

  // Componente de Modal
  const Modal = ({ isOpen, onClose, children }) => {
    if (!isOpen) return null;

    return (
      <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-60">
        <div className="bg-white rounded-lg shadow-lg p-6 max-w-md w-full m-4 transform transition-all animate-fadeIn">
          <div className="flex justify-end">
            <button 
              onClick={onClose}
              className="text-gray-500 hover:text-champions-blue"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
          {children}
        </div>
      </div>
    );
  };

  // Renderizar sección de equipos
  const renderTeamsSection = () => {
    if (!selectedPlayer) {
      return (
        <div className="p-6 bg-white rounded-lg shadow-lg mt-8">
          <h2 className="text-xl font-bold text-champions-blue mb-6 border-b border-gray-200 pb-2">
            Información de Equipos en Champions League
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {players.slice(0, 6).map((player) => (
              <div 
                key={player.position} 
                className="bg-gray-50 rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-all duration-300 cursor-pointer"
                onClick={() => setSelectedPlayer(player)}
              >
                <div className="h-40 overflow-hidden relative">
                  <img 
                    src={`/images/players/${player.position}.${player.position <= 3 ? (player.position === 1 ? 'jpeg' : player.position === 2 ? 'jpg' : 'avif') : 'webp'}`}
                    alt={player.name}
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      e.target.onerror = null;
                      e.target.src = '/images/players/default.jpg';
                    }}
                  />
                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black to-transparent p-2">
                    <p className="text-white font-bold">{player.name}</p>
                  </div>
                </div>
                <div className="p-4">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-sm text-gray-600">Total de Equipos:</span>
                    <span className="font-bold text-champions-blue">{player.fullData.equipos.length}</span>
                  </div>
                  <div className="text-sm text-gray-500 mb-2">
                    {player.fullData.equipos.slice(0, 2).map((team, idx) => (
                      <div key={idx} className="flex justify-between">
                        <span>{team.equipo}</span>
                        <span className="font-medium">{team.goles} goles</span>
                      </div>
                    ))}
                    {player.fullData.equipos.length > 2 && <div className="text-xs text-center mt-1">Y más equipos...</div>}
                  </div>
                </div>
              </div>
            ))}
          </div>

          <p className="text-center mt-6 text-gray-500">Selecciona un jugador para ver todos sus equipos y estadísticas</p>
        </div>
      );
    }

    return (
      <div className="p-6 bg-white rounded-lg shadow-lg mt-8 animate-fadeIn">
        <div className="flex justify-between items-center mb-6 border-b border-gray-200 pb-2">
          <h2 className="text-xl font-bold text-champions-blue">
            Equipos de {selectedPlayer.name}
          </h2>
          <button 
            onClick={() => setSelectedPlayer(null)}
            className="text-gray-500 hover:text-champions-blue"
          >
            <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex flex-col md:flex-row md:space-x-6">
          <div className="md:w-1/3 mb-6 md:mb-0">
            <div className="rounded-lg overflow-hidden shadow-lg mb-4">
              <img 
                src={`/images/players/${selectedPlayer.position}.${selectedPlayer.position <= 3 ? (selectedPlayer.position === 1 ? 'jpeg' : selectedPlayer.position === 2 ? 'jpg' : 'avif') : 'webp'}`}
                alt={selectedPlayer.name}
                className="w-full h-full object-cover"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = '/images/players/default.jpg';
                }}
              />
            </div>
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-bold text-champions-blue mb-2">{selectedPlayer.name}</h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-600">Nacionalidad:</span>
                  <span className="font-medium">{selectedPlayer.fullData.nacionalidad}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Goles Totales:</span>
                  <span className="font-bold text-champions-blue">{selectedPlayer.goals}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Posición:</span>
                  <span className="font-medium">#{selectedPlayer.position}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="md:w-2/3">
            <h3 className="text-lg font-bold text-champions-blue mb-4">Equipos en Champions League</h3>
            <div className="space-y-4">
              {selectedPlayer.fullData.equipos.map((team, idx) => (
                <div key={idx} className="bg-gray-50 rounded-lg p-4 shadow-sm hover:shadow-md transition-all duration-300 flex justify-between items-center">
                  <div className="flex items-center">
                    <div className="bg-champions-blue rounded-full w-10 h-10 flex items-center justify-center text-white font-bold mr-3">
                      {idx + 1}
                    </div>
                    <div>
                      <h4 className="font-bold">{team.equipo}</h4>
                      <p className="text-sm text-gray-500">Champions League</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="flex items-center">
                      <span className="text-champions-gold text-lg mr-2">⚽</span>
                      <span className="text-2xl font-bold text-champions-blue">{team.goles}</span>
                    </div>
                    <p className="text-xs text-gray-500">goles anotados</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-6 bg-blue-50 p-4 rounded-lg border border-blue-100">
              <h3 className="font-bold text-champions-blue mb-2">Datos Curiosos</h3>
              <p className="text-sm text-gray-600">
                {selectedPlayer.name} ha jugado para {selectedPlayer.fullData.equipos.length} {selectedPlayer.fullData.equipos.length === 1 ? 'equipo' : 'equipos'} en la UEFA Champions League, consiguiendo un total de {selectedPlayer.goals} goles a lo largo de su carrera en esta competición.
              </p>
              <p className="text-sm text-gray-600 mt-2">
                Su mejor rendimiento fue con {selectedPlayer.fullData.equipos.sort((a, b) => b.goles - a.goles)[0].equipo} donde anotó {selectedPlayer.fullData.equipos.sort((a, b) => b.goles - a.goles)[0].goles} goles.
              </p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Renderizar sección de temporadas
  const renderSeasonsSection = () => {
    if (!selectedPlayer) {
      return (
        <div className="p-6 bg-white rounded-lg shadow-lg mt-8">
          <h2 className="text-xl font-bold text-champions-blue mb-6 border-b border-gray-200 pb-2">
            Temporadas Destacadas en Champions League
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {players.slice(0, 6).map((player) => (
              <div 
                key={player.position} 
                className="bg-gray-50 rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-all duration-300 cursor-pointer"
                onClick={() => setSelectedPlayer(player)}
              >
                <div className="relative">
                  <div className="absolute top-2 right-2 bg-champions-blue text-white rounded-full px-3 py-1 text-sm font-bold">
                    #{player.position}
                  </div>
                  <img 
                    src={`/images/players/${player.position}.${player.position <= 3 ? (player.position === 1 ? 'jpeg' : player.position === 2 ? 'jpg' : 'avif') : 'webp'}`}
                    alt={player.name}
                    className="w-full h-40 object-cover"
                    onError={(e) => {
                      e.target.onerror = null;
                      e.target.src = '/images/players/default.jpg';
                    }}
                  />
                </div>
                <div className="p-4">
                  <h3 className="font-bold text-champions-blue truncate">{player.name}</h3>
                  <div className="mt-3 bg-blue-50 p-2 rounded-lg">
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-gray-600">Mejor Temporada:</span>
                      <span className="font-bold text-champions-blue">{player.fullData.temporada_max_goles}</span>
                    </div>
                    <div className="flex justify-between items-center mt-1">
                      <span className="text-sm text-gray-600">Goles:</span>
                      <span className="font-bold text-champions-gold">{player.fullData.max_goles_temporada}</span>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <p className="text-center mt-6 text-gray-500">Selecciona un jugador para ver detalles de su mejor temporada</p>
        </div>
      );
    }

    return (
      <div className="p-6 bg-white rounded-lg shadow-lg mt-8 animate-fadeIn">
        <div className="flex justify-between items-center mb-6 border-b border-gray-200 pb-2">
          <h2 className="text-xl font-bold text-champions-blue">
            Mejor Temporada de {selectedPlayer.name}
          </h2>
          <button 
            onClick={() => setSelectedPlayer(null)}
            className="text-gray-500 hover:text-champions-blue"
          >
            <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex flex-col md:flex-row md:space-x-6">
          <div className="md:w-1/3 mb-6 md:mb-0">
            <div className="rounded-lg overflow-hidden shadow-lg">
              <img 
                src={`/images/players/${selectedPlayer.position}.${selectedPlayer.position <= 3 ? (selectedPlayer.position === 1 ? 'jpeg' : selectedPlayer.position === 2 ? 'jpg' : 'avif') : 'webp'}`}
                alt={selectedPlayer.name}
                className="w-full h-auto object-cover"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = '/images/players/default.jpg';
                }}
              />
            </div>

            <div className="mt-4 bg-gray-50 p-4 rounded-lg">
              <div className="text-center mb-3">
                <h3 className="font-bold text-champions-blue">{selectedPlayer.name}</h3>
                <p className="text-sm text-gray-500">{selectedPlayer.fullData.nacionalidad}</p>
              </div>

              <div className="space-y-2">
                <div className="flex justify-between">
                  <span className="text-gray-600">Fecha de Nacimiento:</span>
                  <span className="font-medium">{selectedPlayer.fullData.fecha_nacimiento}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Total de Goles:</span>
                  <span className="font-bold text-champions-blue">{selectedPlayer.goals}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Equipos:</span>
                  <span className="font-medium">{selectedPlayer.fullData.equipos.length}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="md:w-2/3">
            <div className="bg-blue-50 p-6 rounded-lg shadow-md border border-blue-100">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-bold text-champions-blue">Temporada {selectedPlayer.fullData.temporada_max_goles}</h3>
                <div className="bg-champions-blue rounded-full px-4 py-2 text-white font-bold">
                  {selectedPlayer.fullData.max_goles_temporada} Goles
                </div>
              </div>

              <div className="bg-white p-4 rounded-lg shadow-sm mb-4">
                <h4 className="text-lg font-semibold text-champions-blue mb-2">Rendimiento Destacado</h4>
                <p className="text-gray-600">
                  Durante la temporada {selectedPlayer.fullData.temporada_max_goles}, {selectedPlayer.name} alcanzó su máximo rendimiento goleador en la UEFA Champions League, convirtiendo un total de {selectedPlayer.fullData.max_goles_temporada} goles.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div className="bg-white p-4 rounded-lg shadow-sm">
                  <h4 className="font-semibold text-champions-blue mb-2">Contexto Histórico</h4>
                  <p className="text-sm text-gray-600">
                    {selectedPlayer.position <= 10 ? `Como uno de los 10 máximos goleadores históricos, ${selectedPlayer.name} ha dejado una huella imborrable en la competición más prestigiosa a nivel de clubes.` : `${selectedPlayer.name} forma parte del selecto grupo de jugadores que han conseguido brillar en la máxima competición de clubes europea.`}
                  </p>
                </div>

                <div className="bg-white p-4 rounded-lg shadow-sm">
                  <h4 className="font-semibold text-champions-blue mb-2">Equipo Principal</h4>
                  <p className="text-sm text-gray-600">
                    Durante su mejor temporada, {selectedPlayer.name} jugaba con el {selectedPlayer.fullData.equipos.sort((a, b) => b.goles - a.goles)[0].equipo}, donde mostró sus mejores cualidades como goleador.
                  </p>
                </div>
              </div>

              <div className="bg-champions-blue/10 p-4 rounded-lg">
                <h4 className="font-semibold text-champions-blue mb-2 flex items-center">
                  <span className="trophy-icon mr-2">🏆</span> 
                  Logro Destacado
                </h4>
                <p className="text-gray-600">
                  {selectedPlayer.position === 1 
                    ? `Como máximo goleador histórico de la Champions League, ${selectedPlayer.name} ha establecido un récord que será extremadamente difícil de superar.` 
                    : `Con ${selectedPlayer.goals} goles en total, ${selectedPlayer.name} se posiciona en el puesto #${selectedPlayer.position} de los máximos anotadores de la historia de esta prestigiosa competición.`}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Renderizar modal de información del jugador
  const renderPlayerInfoModal = () => (
    <Modal isOpen={activeModal === 'playerInfo'} onClose={closeModal}>
      <h2 className="text-xl font-bold text-champions-blue mb-4 border-b border-gray-200 pb-2">
        {modalData?.title || 'Información del Jugador'}
      </h2>
      {modalData?.player && (
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="text-gray-600">Nacionalidad:</div>
            <div className="font-medium">{modalData.player.nacionalidad}</div>

            <div className="text-gray-600">Fecha de Nacimiento:</div>
            <div className="font-medium">{modalData.player.fecha_nacimiento}</div>

            <div className="text-gray-600">Goles Totales:</div>
            <div className="font-medium text-champions-blue font-bold">{modalData.player.goles_totales}</div>

            <div className="text-gray-600">Mejor Temporada:</div>
            <div className="font-medium">{modalData.player.temporada_max_goles} ({modalData.player.max_goles_temporada} goles)</div>
          </div>
        </div>
      )}
    </Modal>
  );

  return (
    <div className="min-h-screen flex flex-col">
      <ChampionsLeagueHeader 
        onTeamsClick={() => handleSectionChange('teams')}
        onSeasonsClick={() => handleSectionChange('seasons')}
        players={players}
      />

      <main className="flex-grow py-8">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="glass-effect rounded-lg overflow-hidden shadow-lg">
            <div className="p-6 bg-champions-blue text-white relative overflow-hidden">
              <div className="absolute top-0 right-0 opacity-10 w-64 h-64">
                {Array(5).fill('').map((_, i) => (
                  <div key={i} 
                    className="absolute text-champions-gold"
                    style={{
                      fontSize: `${Math.random() * 20 + 20}px`,
                      top: `${Math.random() * 100}%`,
                      left: `${Math.random() * 100}%`,
                      opacity: Math.random() * 0.5 + 0.2,
                      transform: `rotate(${Math.random() * 360}deg)`
                    }}
                  >★</div>
                ))}
              </div>

              <div className="flex items-center mb-4">
                <div className="w-16 h-16 mr-4 overflow-hidden rounded-lg shadow-md border border-champions-gold/30 bg-champions-blue/70">
                  <img 
                    src="/images/logos/cc.png" 
                    alt="Champions League Logo" 
                    className="w-full h-full object-contain transform hover:scale-105 transition-transform duration-300"
                  />
                </div>
                <h1 className="text-3xl font-bold">
                  Máximos Goleadores de la UEFA Champions League
                </h1>
              </div>
              <p className="mt-2 text-blue-100">
                <span className="trophy-icon">🏆</span> 
                Histórico de jugadores con más goles en la competición
              </p>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-100">
                  <tr>
                    <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Pos</th>
                    <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Jugador</th>
                    <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Equipos</th>
                    <th className="py-3 px-4 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                      <span className="flex items-center justify-center">
                        <span className="trophy-icon text-lg">⚽</span> Goles
                      </span>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {players.map((player) => (
                    <PlayerRow
                      key={player.position}
                      position={player.position}
                      name={player.name}
                      team={player.team}
                      goals={player.goals}
                      fullData={player.fullData}
                      onPlayerInfoClick={() => showPlayerInfo(player)}
                    />
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Secciones detalladas */}
          {selectedSection === 'teams' && renderTeamsSection()}
          {selectedSection === 'seasons' && renderSeasonsSection()}

        </div>
      </main>

      {/* Renderizar modales */}
      {renderPlayerInfoModal()}

      <ChampionsLeagueFooter />
    </div>
  );
};

export default ChampionsLeagueScorers;
